def consolidate_legacy_school_services(apps, schema_editor):
    """
    Earlier migrations converted campus services into school services.
    Reconcile duplicate (school, level) pairs before adding uniqueness.

    Population history is preserved. If two services have current population
    for the same year, demote the duplicate before reassignment.
    """
    Service = apps.get_model("crm", "SchoolEducationalService")
    Population = apps.get_model("crm", "SchoolPopulationRecord")
    EditorialUsage = apps.get_model("crm", "SchoolEditorialUsage")
    db = schema_editor.connection.alias

